import{_ as a,o as t,c as s,a5 as i}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Workspace Task views — real Campaign data (2026-10-15)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/workspace-task-real-data/spec.md","filePath":"feature/content-task-workflow/workspace-task-real-data/spec.md"}'),o={name:"feature/content-task-workflow/workspace-task-real-data/spec.md"};function r(n,e,l,c,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="workspace-task-views-—-real-campaign-data-2026-10-15" tabindex="-1">Workspace Task views — real Campaign data (2026-10-15) <a class="header-anchor" href="#workspace-task-views-—-real-campaign-data-2026-10-15" aria-label="Permalink to &quot;Workspace Task views — real Campaign data (2026-10-15)&quot;">​</a></h1><h2 id="objective-actors" tabindex="-1">Objective / actors <a class="header-anchor" href="#objective-actors" aria-label="Permalink to &quot;Objective / actors&quot;">​</a></h2><p>DA-979 / FR 3.6.4–3.6.8: keep the existing Task views, replacing their implicit mock fallback with actual Workspace Tasks. Owner/Manager/Creator/Client must be active members. Existing BA lets Client view all Tasks, including manual Tasks. References: <code>../3-6-4-list-task-view/spec.md</code>, <code>../3-6-8-view-task-filter/spec.md</code>, <code>../../../BA/05-content-task-workflow.md</code>, Media Campaign delivery and Content Request acceptance code.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Fetch <code>/api/v1/workspaces/{id}/tasks</code>. Read the same Mongo <code>tasks</code> used by Campaign deployment and Content Request acceptance, retaining IDs, campaign/source links. No duplicate/synthetic Tasks, init/migration, seed or backfill.</li><li>Include Campaign, supplemental Content Request and manual Tasks scoped to this Workspace. Undeployed planned work items are not Tasks. Support all five existing Task types and all nine statuses including CANCELLED.</li><li>Server-side status/type/search filters combine with AND before pagination; search name/description as literal text. Optional campaignId filter remains Workspace-scoped. Keep existing page/sort defaults and whitelist sort keys; stable ID tie-break.</li><li>Empty API results stay empty. Errors/401/403/invalid envelopes never silently switch to mock; show a retryable error, never another Workspace&#39;s stale rows. Only names/avatars and Task metadata are exposed, no User entity or credentials.</li><li>User confirmed read-only integration this release: no fake Kanban status updates, Calendar moves or Gantt date changes. Only actual deadline instants are visualised; no generated dates, durations, venues or priorities. Missing deadline/priority is displayed as missing. List/board/calendar/timeline share current filters/page, with pagination reachable from every view.</li><li>Task click shows a read-only detail summary of actual list metadata, including Campaign and source Request links. Do not send non-Post Tasks or Clients into the Post editor.</li></ul><h2 id="ui-states" tabindex="-1">UI states <a class="header-anchor" href="#ui-states" aria-label="Permalink to &quot;UI states&quot;">​</a></h2><p>Preserve the current layout and semantic theme tokens. New labels/messages are parallel <code>tasks.*</code> keys in <code>src/i18n/locales/{vi,en}/tasks.json</code>. Loading, empty, error/retry and unavailable fields are distinct; keyboard-operable buttons/dialog, visible labels, light/dark supported. Date-only visualisations refer to deadline, not posting time or planned duration.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>Approval/assignment/start/drag-and-drop mutations, specialised Task editors, Task phase-1 stash, Campaign/package terms, new account/data, database schema changes, auto commit/push, full completion of all Task-view FRs.</p><h2 id="demo-isolation-correction-2026-10-16-user-confirmed" tabindex="-1">Demo isolation correction (2026-10-16, user confirmed) <a class="header-anchor" href="#demo-isolation-correction-2026-10-16-user-confirmed" aria-label="Permalink to &quot;Demo isolation correction (2026-10-16, user confirmed)&quot;">​</a></h2><ul><li>GET Task list is strictly read-only, including empty Workspaces or Workspaces containing only <code>Untitled post</code> Tasks. It must not invoke a sample seeder or assign Tasks to the viewer.</li><li>Preserve existing demo Tasks and the explicit development Mongo seed entrypoint. Do not change Editor/Post/publishing APIs or another member&#39;s approval module.</li><li>The separate, existing Request/Task migrations may be applied after isolated rehearsal and clean preflight; preserve legacy status values and all existing Task documents. Request V2 normalizes only its existing Request fields. No init, bulk seed, Task backfill, automatic deployment retry or external publication.</li></ul>',11)])])}const k=a(o,[["render",r]]);export{u as __pageData,k as default};
